contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address receiver, uint256 amount) public payable {
        require(address(this).balance >= amount);

        // Snapshot balances before the deciding call
        uint256 cBefore = address(c).balance;
        uint256 rBefore = receiver.balance;

        // Drive c through the public entry `sendTo`, optionally as `caller`
        // We can only influence msg.sender by making this contract the caller,
        // but the rule must hold for every input, so we test with our own address.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(address(c).balance == cBefore - amount);
            assert(receiver.balance == rBefore + amount);
            assert(receiver != address(0));
            assert(amount > 0);
        } else {
            // If the call reverted, no Ether should have moved.
            assert(address(c).balance == cBefore);
            assert(receiver.balance == rBefore);
        }
    }

    receive() external payable {}
}

